+    createRectangle: () => shape("rectangle"),
+    createText: () => shape("text"),
+    group: (children: MockShape[]) => Object.assign(shape("group"), { children }),
+    uploadMediaData: async () => ({ id: "fixture-media", width: 1, height: 1 }),
