+
+penpot.ui.onMessage<{ action: string; size?: number; pageId?: string; pageIds?: string[] }>(async (message) => {
+  if (message.action === "cancel") { cancelled = true; return; }
+  if (busy) return;
+  busy = true;
+  try {
+    if (message.action === "run") {
+      const scene = singleBoardScene(message.size!);
+      validateScenes([scene]);
+      cancelled = false;
+      const page = penpot.createPage();
+      page.name = `${pagePrefix}${message.size}`;
+      penpot.openPage(page);
+      if (saveListener) penpot.off(saveListener);
+      let result: unknown;
+      saveListener = penpot.on("contentsave", () => { if (result) send({ type: "save-observed", result }); });
+      const started = profileNow();
+      let metrics: ImportMetrics | undefined;
+      const boards = await importScenes([scene], { isCancelled: () => cancelled,
+        onProgress: (completed, total) => send({ type: "progress", completed, total }),
+        onMetrics: (value) => { metrics = value; }
